import {Component,Suspense,createContext,use,useState,type ReactNode} from "react";import {fetchTicket,type Ticket} from "./resources";
export const LocaleContext=createContext<"pl"|"en">("pl");
export function TicketDetails({ticketPromise}:{ticketPromise:Promise<Ticket>}){const ticket=use(ticketPromise);return <article><h2>{ticket.title}</h2><p>Numer: {ticket.id}</p></article>;}
export function OptionalHint({show}:{show:boolean}){if(!show)return null;const locale=use(LocaleContext);return <p>{locale==="pl"?"Sprawdź szczegóły przed zmianą statusu.":"Review details before changing status."}</p>;}
export class TicketErrorBoundary extends Component<{children:ReactNode;onRetry:()=>void},{failed:boolean}>{state={failed:false};static getDerivedStateFromError(){return {failed:true};}render(){return this.state.failed?<section role="alert"><p>Nie udało się otworzyć ticketu.</p><button type="button" onClick={this.props.onRetry}>Ponów</button></section>:this.props.children;}}
export function TicketPreview({id=42,load=fetchTicket}:{id?:number;load?:(id:number)=>Promise<Ticket>}){const [attempt,setAttempt]=useState<{id:number;promise:Promise<Ticket>;key:number}|null>(null);function open(){const promise=load(id);setAttempt(previous=>({id,promise,key:(previous?.key??0)+1}));}return <section><button type="button" onClick={open}>Otwórz ticket #{id}</button>{attempt&&<TicketErrorBoundary key={attempt.key} onRetry={open}><p>Podgląd #{attempt.id}</p><Suspense fallback={<p role="status">Ładowanie ticketu…</p>}><TicketDetails ticketPromise={attempt.promise}/></Suspense></TicketErrorBoundary>}</section>;}

