import {act,fireEvent,render,screen} from "@testing-library/react";import {expect,test,vi} from "vitest";import {deferred,createTicketResources,fetchTicket,parseTicket,type Ticket} from "./resources";import {LocaleContext,OptionalHint,TicketDetails,TicketErrorBoundary,TicketPreview} from "./TicketPreview";import {Suspense,type ReactElement} from "react";async function mount(element:ReactElement){let view!:ReturnType<typeof render>;await act(async()=>{view=render(element);});return view;}
test("handler rozpoczyna jedno żądanie, fallback znika po danych",async()=>{const task=deferred<Ticket>(),load=vi.fn(()=>task.promise);await mount(<TicketPreview load={load}/>);expect(load).not.toHaveBeenCalled();await act(async()=>{fireEvent.click(screen.getByRole("button",{name:"Otwórz ticket #42"}));});expect(load).toHaveBeenCalledExactlyOnceWith(42);expect(screen.getByRole("status")).toHaveTextContent("Ładowanie ticketu");await act(async()=>task.resolve({id:42,title:"Eksport CSV"}));expect(await screen.findByRole("heading",{name:"Eksport CSV"})).toBeVisible();expect(screen.queryByRole("status")).not.toBeInTheDocument();expect(load).toHaveBeenCalledTimes(1);});
test("rerender rodzica nie rozpoczyna nowego pobierania",async()=>{const task=deferred<Ticket>(),load=vi.fn(()=>task.promise);const view=await mount(<TicketPreview load={load}/>);await act(async()=>{fireEvent.click(screen.getByRole("button"));});view.rerender(<TicketPreview id={7} load={load}/>);expect(screen.getByText("Podgląd #42")).toBeVisible();await act(async()=>task.resolve({id:42,title:"Stary podgląd"}));expect(load).toHaveBeenCalledTimes(1);expect(screen.getByRole("heading")).toHaveTextContent("Stary podgląd");});
test("odrzucenie trafia do granicy błędów, retry tworzy nową próbę",async()=>{const first=deferred<Ticket>(),second=deferred<Ticket>(),load=vi.fn<(id:number)=>Promise<Ticket>>().mockReturnValueOnce(first.promise).mockReturnValueOnce(second.promise);const log=vi.spyOn(console,"error").mockImplementation(()=>{});try{await mount(<TicketPreview load={load}/>);await act(async()=>{fireEvent.click(screen.getByRole("button"));});await act(async()=>first.reject(Error("404")));expect(await screen.findByRole("alert")).toHaveTextContent("Nie udało się otworzyć");expect(screen.queryByRole("status")).not.toBeInTheDocument();await act(async()=>{fireEvent.click(screen.getByRole("button",{name:"Ponów"}));});expect(screen.getByRole("status")).toBeVisible();await act(async()=>second.resolve({id:42,title:"Po ponowieniu"}));expect(await screen.findByRole("heading",{name:"Po ponowieniu"})).toBeVisible();expect(load).toHaveBeenCalledTimes(2);}finally{log.mockRestore();}});
test("późna odpowiedź starej próby nie nadpisuje nowej",async()=>{const first=deferred<Ticket>(),second=deferred<Ticket>(),load=vi.fn<(id:number)=>Promise<Ticket>>().mockReturnValueOnce(first.promise).mockReturnValueOnce(second.promise);await mount(<TicketPreview load={load}/>);await act(async()=>{fireEvent.click(screen.getByRole("button"));});await act(async()=>{fireEvent.click(screen.getByRole("button"));});await act(async()=>second.resolve({id:42,title:"Nowsza próba"}));await act(async()=>first.resolve({id:42,title:"Stara próba"}));expect(screen.getByRole("heading")).toHaveTextContent("Nowsza próba");});
test("use kontekstu po warunku reaguje na provider bez naruszenia innych hooków",()=>{const view=render(<LocaleContext.Provider value="pl"><OptionalHint show={false}/></LocaleContext.Provider>);expect(screen.queryByText(/szczegóły/)).not.toBeInTheDocument();view.rerender(<LocaleContext.Provider value="pl"><OptionalHint show/></LocaleContext.Provider>);expect(screen.getByText(/szczegóły/)).toBeVisible();view.rerender(<LocaleContext.Provider value="en"><OptionalHint show/></LocaleContext.Provider>);expect(screen.getByText(/Review details/)).toBeVisible();});
test("zasób ma stabilną Promise do jawnego unieważnienia, zakresy są niezależne",async()=>{const load=vi.fn(async(id:number)=>({id,title:"Ticket "+id})),a=createTicketResources(load),b=createTicketResources(load);const first=a.prepare(42);expect(a.prepare(42)).toBe(first);expect(b.prepare(42)).not.toBe(first);a.invalidate(42);expect(a.prepare(42)).not.toBe(first);a.clear();expect(a.prepare(42)).not.toBe(first);expect(load).toHaveBeenCalledTimes(4);await first;});
test("adapter odróżnia HTTP 404, niepoprawne dane i poprawną odpowiedź",async()=>{const missing=vi.fn<typeof fetch>().mockResolvedValue(new Response(null,{status:404}));await expect(fetchTicket(42,missing)).rejects.toThrow("Nie znaleziono ticketu");await expect(fetchTicket(0,missing)).rejects.toThrow("Niepoprawne ID");expect(missing).toHaveBeenCalledTimes(1);const bad=vi.fn<typeof fetch>().mockResolvedValue(Response.json({id:42,title:7}));await expect(fetchTicket(42,bad)).rejects.toThrow("Niepoprawne dane");const good=vi.fn<typeof fetch>().mockResolvedValue(Response.json({id:42,title:"API"}));await expect(fetchTicket(42,good)).resolves.toEqual({id:42,title:"API"});expect(()=>parseTicket(null)).toThrow();});
test("spełniona Promise jest odczytywana bez ręcznego loading w dziecku",async()=>{const promise=Promise.resolve({id:7,title:"Gotowe"});await act(async()=>{render(<TicketErrorBoundary onRetry={()=>{}}><Suspense fallback={<p role="status">Czekaj</p>}><TicketDetails ticketPromise={promise}/></Suspense></TicketErrorBoundary>);});expect(screen.getByRole("heading")).toHaveTextContent("Gotowe");});

