test("późna odpowiedź starej próby nie nadpisuje nowej",async()=>{const first=deferred<Ticket>(),second=deferred<Ticket>(),load=vi.fn<(id:number)=>Promise<Ticket>>().mockReturnValueOnce(first.promise).mockReturnValueOnce(second.promise);await mount(<TicketPreview load={load}/>);await act(async()=>{fireEvent.click(screen.getByRole("button"));});await act(async()=>{fireEvent.click(screen.getByRole("button"));});await act(async()=>second.resolve({id:42,title:"Nowsza próba"}));await act(async()=>first.resolve({id:42,title:"Stara próba"}));expect(screen.getByRole("heading")).toHaveTextContent("Nowsza próba");});
