export type Ticket={id:number;title:string};export function deferred<T>(){let resolve!:(value:T)=>void,reject!:(reason:unknown)=>void;const promise=new Promise<T>((yes,no)=>{resolve=yes;reject=no;});return {promise,resolve,reject};}
export function parseTicket(raw:unknown):Ticket{if(!raw||typeof raw!=="object")throw Error("Niepoprawne dane ticketu");const value=raw as Record<string,unknown>;if(typeof value.id!=="number"||!Number.isSafeInteger(value.id)||value.id<1||typeof value.title!=="string"||!value.title.trim())throw Error("Niepoprawne dane ticketu");return {id:value.id,title:value.title};}
export async function fetchTicket(id:number,request:typeof fetch=fetch):Promise<Ticket>{if(!Number.isSafeInteger(id)||id<1)throw Error("Niepoprawne ID");const response=await request("/api/tickets/"+id);if(!response.ok)throw Error(response.status===404?"Nie znaleziono ticketu":"Nie udało się pobrać ticketu");return parseTicket(await response.json());}
// Fabryka zasobu należy do konkretnego zakresu użytkownika/żądania. Brak globalnej mapy danych kont.
export function createTicketResources(load:(id:number)=>Promise<Ticket>){const cache=new Map<number,Promise<Ticket>>();return {prepare(id:number){if(!Number.isSafeInteger(id)||id<1)throw Error("Niepoprawne ID");let promise=cache.get(id);if(!promise){promise=load(id);cache.set(id,promise);}return promise;},invalidate(id:number){cache.delete(id);},clear(){cache.clear();}};}

